SELECT 
FROM mt_promotion_bid_record
WHERE shop_id = #{shopId}
  AND biz_date = #{bizDate}
  AND slot_time = #{slotTime}
LIMIT 1

SELECT 
FROM mt_promotion_bid_record
WHERE shop_id = #{shopId}
  AND window_key = #{windowKey}
  AND execute_status = 'SUCCESS'
ORDER BY slot_time DESC, id DESC
LIMIT #{limit}

SELECT 
FROM mt_promotion_bid_record
WHERE shop_id = #{shopId}
  AND biz_date >= #{bizDateFrom}
  AND (log_markdown_status IS NULL OR log_markdown_status != 'PENDING')
ORDER BY slot_time DESC, id DESC

SELECT 
FROM mt_promotion_bid_record
WHERE shop_id = #{shopId}
  AND decision_reason = #{decisionReason}
ORDER BY slot_time DESC, id DESC
LIMIT 1

SELECT 
FROM mt_promotion_bid_record
WHERE shop_id = #{shopId}
  AND biz_date = #{bizDate}
  AND decision_reason = #{decisionReason}
ORDER BY slot_time DESC, id DESC
LIMIT 1

SELECT 
FROM mt_promotion_bid_record
WHERE shop_id = #{shopId}
  AND execute_status = 'SUCCESS'
  AND biz_date >= #{bizDateFrom}
ORDER BY slot_time DESC, id DESC
LIMIT #{limit}

SELECT COUNT(1)
FROM mt_promotion_bid_record
WHERE shop_id = #{shopId}
  AND id > #{recordId}
  AND (log_markdown_status IS NULL OR log_markdown_status != 'PENDING')

SELECT COALESCE(SUM(total_cost), 0)
FROM mt_promotion_bid_record
WHERE shop_id = #{shopId}
  AND execute_status = 'SUCCESS'
  AND biz_date >= #{bizDateFrom}
  AND biz_date < #{bizDateToExclusive}

SELECT r.id, r.shop_id AS shopId, sh.poi_id AS poiId, sh.epoi_id AS epoiId, COALESCE(sh.poi_name, sh.name) AS shopName, r.biz_date AS bizDate, r.slot_time AS slotTime, r.window_key AS windowKey, r.window_start_at AS windowStartAt, r.window_end_at AS windowEndAt, r.previous_bid_amount AS previousBidAmount, r.next_bid_amount AS nextBidAmount, r.decision_action AS decisionAction, r.decision_reason AS decisionReason, r.total_cost AS totalCost, r.total_income AS totalIncome, r.total_cost_ratio AS totalCostRatio, r.cost_delta AS costDelta, r.cost_counter_value AS costCounterValue, r.execute_status AS executeStatus, r.log_markdown_status AS logMarkdownStatus, r.log_task_id AS logTaskId, r.error_msg AS errorMsg, r.create_time AS createTime, r.update_time AS updateTime FROM mt_promotion_bid_record r INNER JOIN mt_shop sh ON sh.id = r.shop_id WHERE 1 = 1
AND r.shop_id = #{shopId}
AND sh.poi_id LIKE CONCAT('%', #{poiId}, '%')
AND COALESCE(sh.poi_name, sh.name) LIKE CONCAT('%', #{shopName}, '%')
AND ( CAST(r.shop_id AS CHAR) = #{keyword} OR sh.poi_id LIKE CONCAT('%', #{keyword}, '%') OR sh.epoi_id LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(sh.poi_name, sh.name) LIKE CONCAT('%', #{keyword}, '%') )
AND r.execute_status = #{executeStatus}
AND r.decision_action = #{decisionAction}
AND r.decision_reason = #{decisionReason}
AND r.log_markdown_status = #{logMarkdownStatus}
AND r.slot_time >= #{slotStartTime}
AND r.slot_time <= #{slotEndTime}
AND EXISTS ( SELECT 1 FROM ai_user_shop_binding usb WHERE usb.shop_id = r.shop_id AND usb.user_id = #{currentUserId} )
AND EXISTS ( SELECT 1 FROM ai_user_shop_binding usb WHERE usb.shop_id = r.shop_id AND usb.user_id IN
#{userId}
)
ORDER BY r.slot_time DESC, r.id DESC

