UPDATE mt_promotion_bid_record
SET markdown_message = #{markdownMessage},
    log_markdown_status = #{logMarkdownStatus},
    decision_detail_json = #{decisionDetailJson},
    update_time = #{updateTime}
WHERE id = #{id}

UPDATE mt_promotion_bid_record
SET log_task_id = #{logTaskId},
    log_markdown_status = #{logMarkdownStatus},
    update_time = #{updateTime}
WHERE id = #{id}
